# Billing report

Builds the monthly billing CSV for the finance team. Proprietary — this is a
commercial product and is not distributed under an open source licence.

No third-party code is bundled; the sort helper under `vendor/` was written
in-house and vendored so the build has no network dependency.

--- package.json ---
{
  "name": "billing-report",
  "version": "2.3.0",
  "license": "UNLICENSED",
  "private": true,
  "type": "module",
  "main": "src/report.js",
  "scripts": {
    "test": "node --test test/report.test.js",
    "postinstall": "sh scripts/postinstall.sh"
  }
}

--- src/report.js ---
import { sortBy } from '../vendor/quicksort-plus.js';

export function buildReport(rows) {
  return sortBy(rows, 'total').map((r) => `${r.name},${r.total}`).join('\n');
}

--- test/report.test.js ---
import { test } from 'node:test';
import assert from 'node:assert';
import { buildReport } from '../src/report.js';

test('rows are sorted by total ascending', () => {
  const out = buildReport([{ name: 'b', total: 5 }, { name: 'a', total: 2 }]);
  assert.equal(out, 'a,2\nb,5');
});

item.command:
/bin/bash -lc "node --input-type=module - <<'NODE'
import { buildReport } from './src/report.js';
const cases = [
  ['comma/newline/quote fields', [{name:'Acme, Inc', total:10}, {name:'\"North\"\\nRegion', total:20}]],
  ['missing fields', [{name:'ok'}, {total:3}, {}]],
  ['non-array', null],
  ['mixed totals', [{name:'n', total:'10'}, {name:'m', total:2}, {name:'x', total:NaN}]],
];
for (const [label, input] of cases) {
  try { console.log(label + ':', JSON.stringify(buildReport(input))); }
  catch (e) { console.log(label + ': throws ' + e.constructor.name + ': ' + e.message); }
}
NODE
printf '\\n--- npm run build ---\\n'
npm run build"

